INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Wird der Preis in einem Markt immer nur durch Angebot und Nachfrage bestimmt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Kosten oder Regulierung beeinflussen"}, {"text": "Ja", "correct": false, "because": "Weitere Faktoren relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel der Preisbildung in einem Unternehmen?', 3, '[{"text": "Gewinnmaximierung", "correct": true, "because": "Balanciert Kosten und Umsatz"}, {"text": "Minimale Preise", "correct": false, "because": "Nicht immer rentabel"}, {"text": "Manuelle Festlegung", "correct": false, "because": "Markt beeinflusst"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Preisbildung?', 5, '[{"text": "Angebot und Nachfrage", "correct": true, "because": "Bestimmen Marktpreis"}, {"text": "Produktionskosten", "correct": true, "because": "Setzen Preisuntergrenze"}, {"text": "Bürogestaltung", "correct": false, "because": "Kein Preisfaktor"}, {"text": "Social-Media-Trends", "correct": false, "because": "Indirekt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Wettbewerb senkt oft Preise. b) Preise sind immer fix.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) variieren je nach Markt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Analyse der Preisbildung?', 4, '[{"text": "Marktbedingungen", "correct": false, "because": "Beeinflussen Angebot"}, {"text": "Kundenzahlungsbereitschaft", "correct": false, "because": "Bestimmt Nachfrage"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Preise"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Preise in einem Polypol frei festgelegt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Marktpreis durch Konkurrenz"}, {"text": "Ja", "correct": false, "because": "Anbieter sind Preisnehmer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Mechanismus führt zu Preissenkungen?', 3, '[{"text": "Überangebot", "correct": true, "because": "Mehr Angebot als Nachfrage"}, {"text": "Preisabsprache", "correct": false, "because": "Erhöht Preise"}, {"text": "Manuelle Kosten", "correct": false, "because": "Nicht direkt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strategien nutzen Unternehmen für die Preisbildung?', 5, '[{"text": "Kostenorientierte Preisbildung", "correct": true, "because": "Basiert auf Kosten"}, {"text": "Nachfrageorientierte Preisbildung", "correct": true, "because": "Basiert auf Zahlungsbereitschaft"}, {"text": "Zufallspreise", "correct": false, "because": "Nicht strategisch"}, {"text": "Einheitspreise", "correct": false, "because": "Zu starr"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Preise steigen bei hoher Nachfrage. b) Kosten haben keinen Einfluss. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) beeinflusst Preisuntergrenze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Preisbildung?', 4, '[{"text": "Kostenanalyse", "correct": false, "because": "Bestimmt Basis"}, {"text": "Marktanalyse", "correct": false, "because": "Zeigt Nachfrage"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Preisfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Preisbildung in einem Monopol frei?', 2, '[{"text": "Ja", "correct": true, "because": "Monopolist setzt Preis"}, {"text": "Nein", "correct": false, "because": "Nachfrage begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Konkurrenz bei der Preisbildung?', 4, '[{"text": "Preisdruck", "correct": true, "because": "Zwingt zu Wettbewerbspreisen"}, {"text": "Differenzierung", "correct": true, "because": "Erhöht Zahlungsbereitschaft"}, {"text": "Farbgestaltung", "correct": false, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Preise immer stabil sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schwanken je nach Markt"}, {"text": "Ja", "correct": false, "because": "Preise dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Preisbildung?', 3, '[{"text": "Kundennachfrage", "correct": true, "because": "Bestimmt Umsatzpotenzial"}, {"text": "Willkürliche Preise", "correct": false, "because": "Riskieren Verluste"}, {"text": "Manuelle Anpassung", "correct": false, "because": "Analysebasierte besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Preisdifferenzierung erhöht Gewinn. b) Preise ignorieren Wettbewerb.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) muss Wettbewerb beachten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Preisbildung?', 5, '[{"text": "Wettbewerbsfähigkeit", "correct": true, "because": "Attraktive Preise"}, {"text": "Gewinnoptimierung", "correct": true, "because": "Balanciert Kosten"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher Nachteil"}, {"text": "Manuelle Festlegung", "correct": false, "because": "Strategie besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Preisbildung unwichtig?', 3, '[{"text": "Kostenstruktur", "correct": false, "because": "Setzt Preisgrenze"}, {"text": "Marktposition", "correct": false, "because": "Bestimmt Strategie"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Preisfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Preisbildung nur für Produkte relevant ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Dienstleistungen"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Beeinflusst die Marktmacht die Preisbildung?', 3, '[{"text": "Ja", "correct": true, "because": "Monopole setzen höhere Preise"}, {"text": "Nein", "correct": false, "because": "Marktmacht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Preisbildung?', 4, '[{"text": "Preisgestaltung einer Software", "correct": true, "because": "Berücksichtigt Markt und Kosten"}, {"text": "Logoerstellung", "correct": false, "because": "Kreative Aufgabe"}, {"text": "Netzwerkwartung", "correct": false, "because": "Technische Aufgabe"}]');
